files.content:
/* viide elemendile st muudame kõiki selliseid elemente */
body {
    display: flex;
    padding: 1em;
    flex-direction: column;
    gap: 3em; /* vahe elementide vahel */
    align-items: center;
}
/* #-ga viitame elemendile, millel on selline id */
#photo {
    max-width: 25em;
    max-height: 30em;
}
/* .-ga viitame elemenditele, millel on selline class */
.container {
    display: flex;
    padding: 1em;
    align-items: center;
    gap: 3em;
    justify-content: center;
}

#textBox {
    max-height: 25em;
    overflow-x: hidden;
    overflow-y: auto;
}

.card {
    width: 20em;
    height: 25em;
    display: flex;
    flex-direction: column;
    align-items: center;
    background-color: #D9D9D9;
    padding: 5em 1.5em 1.5em;
}
.icon {
    max-width: 10em;
}
iframe {
    width: 50em;
    height: 28em;
}

button {
    width: 20em;
    border: none;
    background-color: #D9D9D9;
    padding: 2em;
}

button:hover {
    background-color: #C8C6C6;
    cursor: pointer;
}
